async function api(path,method='GET',value,signal,hydrate=true,responseLive){
 const responseGate=()=>{if(responseLive&&!responseLive())throw new DOMException('Скасовано','AbortError');};
 const request=async(url,options)=>{try{return await fetch(url,options);}catch(error){if(error.name==='AbortError')throw error;throw Error(method==='GET'?'Не вдалося з’єднатися із сервером. Перевірте підключення й повторіть.':'З’єднання перервано. Оновіть список, щоб перевірити результат операції.');}};
 if(!csrf){await tradingReady();csrf=(await window.TradeDirectories.bootstrap()).csrf;}
 responseGate();
 const r=await request('/api/erp/'+path,{method,signal,credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:value===undefined?undefined:JSON.stringify(value)});
 responseGate();
 if(r.status===401){if(!signal?.aborted)window.dispatchEvent(new Event('tsukenya:session-invalidated'));if(!signal?.aborted)location.href='/';throw Object.assign(Error('Сеанс завершився.'),{status:401});}
 let result;try{result=await r.json();}catch{responseGate();throw Error('Сервер не відповідає. Повторіть спробу.');}
 responseGate();
 if(!r.ok)throw Object.assign(Error(result.error||'Не вдалося виконати дію.'),{status:r.status,code:result.code,detail:result});if(method==='GET'&&hydrate)await window.TradeDirectories.hydrateCaptions(result);responseGate();return result;
}
