async function tradingReady(){if(window.TradeDirectories)return;await new Promise(resolve=>window.addEventListener('tsukenya:trading-ready',resolve,{once:true}));}
async function load(){await tradingReady();const state=await window.TradeDirectories.bootstrap();csrf=state.csrf;E={...state,stores:[],warehouses:[],accounts:[],employees:[],parties:[],expense_categories:[]};applyRole();}
function applyRole(){document.querySelectorAll('.tab').forEach(a=>{if(tabs.has(a.dataset.tab))a.hidden=!roles[E.role]?.includes(a.dataset.tab);});if(E.role!=='owner'){document.querySelector('[data-workspace="development"]').hidden=true;document.querySelectorAll('.tab[data-tab="expenses"],.tab[data-tab="ideas"],.tab[data-tab="tasks"],.tab[data-tab="devOverview"]').forEach(x=>x.hidden=true);}}
function errorPanel(error){main().innerHTML=`<section class="panel"><p class="trade-alert error" role="alert">${esc(error.message)}</p>${button('Повторити','refresh')}</section>`;}
function alert(text){return `<div class="trade-alert">${text}</div>`;}
function alertsStatus(){const a=E.alerts_status;if(!a)return'';const at=x=>new Date(x).toLocaleString('uk-UA'),src=x=>x==='scheduler'?'за розкладом':'вручну';return (a.error?`<div class="trade-alert trade-error" role="alert">Помилка контролю операцій ${esc(at(a.error.at))} (${src(a.error.source)}): ${esc(a.error.message)}${a.error.reference?` Код: ${esc(a.error.reference)}.`:''} Задачі можуть бути неактуальними.</div>`:'')+(a.ok?`<p class="trade-caption">Контроль оновлено ${esc(at(a.ok.at))} (${src(a.ok.source)}).${a.stale?' <strong>Давно не оновлювався: запустіть перевірку.</strong>':''}</p>`:'<p class="trade-caption">Контроль операцій ще не запускався.</p>');}
