let editing=null;
function productOptions(selected){return option([],selected,'Виберіть товар');}
function lineMarkup(kind,line={}){const lineField=(label,control,cls)=>`<label class="${cls}"><span>${label}</span>${control}</label>`;const referenced=Boolean(line.reference_line),locked=referenced&&['customer_return','supplier_return'].includes(kind);return `<div class="trade-line ${kind==='sale'?'sale-line':''}"><input type="hidden" data-line="line_key" value="${esc(line.line_key||crypto.randomUUID())}"><input type="hidden" data-line="reference_line" value="${esc(line.reference_line||'')}">${referenced?`<p class="line-origin">Вихідний рядок № ${esc(line.reference_line)}${line.remaining!==undefined?' · доступно '+esc(quantity(line.remaining))+' '+esc(line.unit||''):''}</p>`:''}${field('Товар',`<select data-line="product" required ${locked?'disabled':''}>${productOptions(line.product)}</select>`,'line-field line-product')}${lineField(kind==='inventory'?'Пораховано':kind==='production'?'Фактичний вихід':'Кількість',`<input data-line="quantity" type="number" inputmode="decimal" min="${kind==='inventory'?0:0.001}" step="0.001" value="${esc(line.quantity??1)}" required>`,'line-field line-quantity')}${lineField(kind==='inventory'?'Собівартість надлишку':'Ціна, грн',`<input data-line="price" type="number" inputmode="decimal" min="${['sale','customer_order'].includes(kind)?0.0001:0}" step="0.0001" value="${esc(line.price??0)}" ${!priceKinds.has(kind)?'readonly':''}>`,'line-field line-price')}${kind==='sale'?'<label hidden>Партія<input data-line="lot" value=""></label>':lineField('Партія',`<input data-line="lot" value="${esc(line.lot||'')}" maxlength="80" ${kind==='supplier_return'&&referenced?'readonly':''}>`,'line-field line-lot')}${kind==='sale'?'<label hidden>Придатний до<input data-line="expiry" value=""></label>':lineField('Придатний до',`<input data-line="expiry" type="date" value="${esc(line.expiry||'')}" ${kind==='supplier_return'&&referenced?'readonly':''}>`,'line-field line-expiry')}<div class="line-field line-remove"><span aria-hidden="true">Дії</span>${button('×','remove-line','aria-label="Видалити товарний рядок"')}</div></div>`;}
function clearLineOrigins(d){const version=d.querySelector('[name=order_revision]');if(version)version.value='';d.querySelectorAll('[data-line=reference_line]').forEach(i=>i.value='');d.querySelectorAll('.line-origin').forEach(i=>i.remove());d.querySelectorAll('[data-line=product]').forEach(i=>i.disabled=false);d.querySelectorAll('[data-line=lot],[data-line=expiry]').forEach(i=>i.readOnly=false);}
function paymentMarkup(p={}){return `<div class="trade-payment-row">${field('Рахунок',`<select data-payment="account" required>${option(E.accounts.filter(a=>a.store_id===Number(editing.store)),p.account)}</select>`)}${field('Сума, грн',`<input data-payment="amount" type="number" min="0.01" step="0.01" inputmode="decimal" value="${esc(p.amount||'')}" required>`)}${button('×','remove-payment','aria-label="Видалити спосіб оплати"')}</div>`;}
function updateTotal(){const rows=[...dialog.querySelectorAll('.trade-line')];const scaled=(text,places)=>{const m=String(text||'0').replace(/^\./,'0.').match(/^(\d+)(?:\.(\d*))?$/);if(!m||m[2]?.length>places)return 0n;return BigInt(m[1])*10n**BigInt(places)+BigInt((m[2]||'').padEnd(places,'0')||'0');};const cents=rows.reduce((s,r)=>s+(scaled(r.querySelector('[data-line=quantity]').value,3)*scaled(r.querySelector('[data-line=price]').value,4)+50000n)/100000n,0n);let total=Number(cents)/100;if(editing.kind==='receipt')total+=Number(dialog.querySelector('[name=additional_cost]')?.value||0);const target=dialog.querySelector('#tradeDraftTotal');if(target)target.textContent=editing.kind==='production'?'Собівартість — після проведення':editing.kind==='payroll'?'Нарахування — після проведення':amount(total)+' грн';return total;}
function voucherEmployees(store,selected,kind){return E.employees.filter(e=>e.store_id===Number(store)&&(e.active||kind!=='sale'||String(e.id)===String(selected))).map(e=>e.active?e:{...e,name:`${e.name} (неактивний)`});}
function syncDocumentFields(){const form=dialog.querySelector('#tradeVoucherForm');if(!form)return;editing.store=form.elements.store.value;window.TradeDirectories.sync(form);}
async function chooseReference(){
 const d=dialog,form=d?.querySelector('#tradeVoucherForm');if(!form||d.dataset.busy==='1')return;
 const kind=editing.kind,old=form.elements.reference.value;
 const selected=await documentBrowser.pick({purpose:kind,store:form.elements.store.value,party:form.elements.party?.value,selected:old});
 if(!selected||dialog!==d||!d.open||String(selected.id)===old)return;
 if(kind!=='payment'&&[...d.querySelectorAll('[data-line=product]')].some(input=>input.value)&&!confirm('Замінити товарні рядки даними вибраного документа?'))return;
 const finish=busyDialog(d,'Завантаження вихідного документа…');if(!finish)return;let applied=false;
 try{
  const ref=kind==='payment'?selected:await api('vouchers/'+selected.id);
  if(dialog!==d||!d.open)return;
  if(form.elements.party)window.TradeDirectories.setValue(form.elements.party,ref.party);
  if(form.elements.warehouse&&ref.warehouse)window.TradeDirectories.setValue(form.elements.warehouse,ref.warehouse);
  if(kind==='payment')form.elements.amount.value=ref.outstanding;
  else{
   const remaining=ref.lines.filter(line=>Number(line.remaining??line.quantity)>0).map(line=>({...line,quantity:line.remaining??line.quantity}));
   d.querySelector('#tradeLines').innerHTML=remaining.map(line=>lineMarkup(kind,{...line,line_key:undefined,reference_line:line.id,lot:kind==='supplier_return'?line.lot:'',expiry:kind==='supplier_return'?line.expiry:''})).join('');
   if(['customer_return','supplier_return'].includes(kind)){
    const returnTotal=remaining.reduce((sum,line)=>sum+Number(line.remaining_amount??line.amount),0),refund=Math.max(0,returnTotal-Number(ref.outstanding||0));
    d.querySelector('#tradePayments').innerHTML=refund>0?paymentMarkup({account:'',amount:refund.toFixed(2)}):'';
   }
   updateTotal();
  }
  form.elements.order_revision.value=ref.order?.revision||'';form.elements.reference.value=ref.id;d.querySelector('#tradeReferenceValue').textContent=referenceLabel(selected,kind);d.querySelector('[data-trade=clear-reference]').disabled=false;d.querySelector('[data-reference-warning]')?.remove();markDirty(d);applied=true;
 }catch(error){formError(error,d);}finally{finish();if(d.open){d.querySelector('[data-trade=clear-reference]').disabled=!form.elements.reference.value;if(applied)d.querySelector('#tradeReferenceValue').focus();}}
}
