const pendingActions=new WeakSet();
function runTradeAction(el){if(el.disabled||pendingActions.has(el)||el.closest('dialog')?.dataset.busy==='1')return;const wasAriaDisabled=el.getAttribute('aria-disabled'),d=el.closest('dialog');pendingActions.add(el);el.setAttribute('aria-disabled','true');Promise.resolve(act(el.dataset.trade,el)).catch(error=>formError(error,d||dialog)).finally(()=>{pendingActions.delete(el);if(el.isConnected){if(wasAriaDisabled===null)el.removeAttribute('aria-disabled');else el.setAttribute('aria-disabled',wasAriaDisabled);}});}
