document.addEventListener('toggle',e=>{if(!main().contains(e.target))return;if(e.target.dataset?.disclosure==='stock-assortment'&&assortmentOpen!==e.target.open){assortmentOpen=e.target.open;draw().catch(errorPanel);}if(e.target.dataset?.disclosure==='stock-lots'&&lotsOpen!==e.target.open){lotsOpen=e.target.open;draw().catch(errorPanel);}},true);
document.addEventListener('change',e=>{if(!main().contains(e.target))return;captureAssortmentDraft(e.target);if(e.target.name==='filterStore'){filterStore=e.target.value;stockWarehouse='';listPage=stockPage=lotsPage=1;draw().catch(errorPanel);}if(e.target.name==='stockWarehouse'){stockWarehouse=e.target.value;stockPage=lotsPage=1;draw().catch(errorPanel);}if(e.target.name==='assortmentWarehouse'){assortmentWarehouse=e.target.value;assortmentNotice=null;assortmentPage=1;assortmentProduct='';draw().catch(errorPanel);}if(e.target.name==='filterStatus'){filterStatus=e.target.value;listPage=1;draw().catch(errorPanel);}});
// Only the draw that actually replaces the list restores the search field, with the text and caret as they are at that moment.
function searchFocus(){const a=document.activeElement;if(!a||!main().contains(a))return null;let selector;
 if(['stockSearch','partySearch'].includes(a.name))selector=`[name=${a.name}]`;
 else if(a.dataset.assortmentSold)selector=`[data-assortment-sold="${CSS.escape(a.dataset.assortmentSold)}"]`;
 else if(a.dataset.assortmentMin)selector=`[data-assortment-min="${CSS.escape(a.dataset.assortmentMin)}"]`;
 else if(['assortment-save','assortment-reset'].includes(a.dataset.trade))selector=`[data-trade="${a.dataset.trade}"][data-product="${CSS.escape(a.dataset.product)}"]`;
 else return null;
 const {value,selectionStart:start,selectionEnd:end,selectionDirection:direction}=a;return ()=>{const x=main().querySelector(selector);if(!x)return;if(['stockSearch','partySearch'].includes(a.name))x.value=value;x.focus({preventScroll:true});try{x.setSelectionRange(start,end,direction||'none');}catch(_){}};
}
